const CORE_QUIZ_BANK=[
{id:'g01',category:'Governança e Gestão de TI',topic:'p6-6',prompt:'Um serviço de e-mail parou inesperadamente. Na prática de gerenciamento de incidentes, qual é o objetivo principal?',options:['Descobrir definitivamente todas as causas do defeito','Restaurar a operação normal do serviço o mais rápido possível','Eliminar a necessidade de acordos de serviço','Substituir o gerenciamento de mudanças'],answer:1,explanation:'O gerenciamento de incidentes busca minimizar o impacto negativo dos incidentes, restaurando a operação normal do serviço o mais rápido possível. A investigação de causas é foco do gerenciamento de problemas.'},
{id:'g02',category:'Governança e Gestão de TI',topic:'p6-7',prompt:'Vários incidentes semelhantes voltam a ocorrer. Qual prática se concentra em investigar causas reais ou potenciais desses incidentes?',options:['Gerenciamento de problemas','Gerenciamento de requisições de serviço','Gerenciamento de níveis de serviço','Gerenciamento financeiro'],answer:0,explanation:'A prática de problemas investiga causas reais ou potenciais de incidentes e gerencia soluções de contorno e erros conhecidos. Um problema não é sinônimo de um incidente isolado.'},
{id:'g03',category:'Governança e Gestão de TI',topic:'p6-10',prompt:'Qual alternativa melhor descreve um SLA?',options:['Uma lista de todas as senhas administrativas','Um acordo documentado entre provedor e cliente que identifica os serviços requeridos e o nível esperado','Um relatório que sempre substitui o contrato de fornecimento','Uma proibição de mudanças no serviço'],answer:1,explanation:'Um acordo de nível de serviço documenta serviços e níveis esperados entre provedor e cliente. Não é um inventário de credenciais nem elimina contratos ou mudanças.'},
{id:'g04',category:'Governança e Gestão de TI',topic:'p6-9',prompt:'Na gestão de configuração, um item de configuração é:',options:['Exclusivamente um equipamento físico','Apenas um arquivo de texto com parâmetros','Um componente que precisa ser gerenciado para entregar um serviço de TI','Qualquer dado pessoal de um usuário, obrigatoriamente'],answer:2,explanation:'Um item de configuração pode ser hardware, software, documentação ou outro componente relevante para o serviço. O conceito não se limita a equipamentos físicos.'},
{id:'g05',category:'Governança e Gestão de TI',topic:'p6-8',prompt:'Uma equipe propõe uma alteração em produção. Qual conduta é compatível com a habilitação de mudanças da ITIL 4?',options:['Executar qualquer alteração sem avaliar impacto','Buscar maximizar mudanças bem-sucedidas com avaliação de riscos e autorização apropriada','Proibir permanentemente qualquer alteração','Tratar toda mudança como um incidente de segurança'],answer:1,explanation:'A prática de habilitação de mudanças busca maximizar mudanças bem-sucedidas, avaliando riscos, autorizando de forma apropriada e gerenciando o calendário de mudanças.'},
{id:'g06',category:'Governança e Gestão de TI',topic:'p6-5',prompt:'Na ITIL 4, a criação de valor em serviços é entendida principalmente como:',options:['Uma atividade exclusiva do fornecedor','A simples compra de equipamentos novos','Uma cocriação que envolve provedor, consumidor e outras partes interessadas','Uma medição feita somente pelo custo de aquisição'],answer:2,explanation:'A ITIL 4 enfatiza a cocriação de valor nas relações de serviço. Valor não é produzido unilateralmente nem se resume ao custo de equipamentos.'},
{id:'g07',category:'Governança e Gestão de TI',topic:'p6-4',prompt:'No COBIT, o domínio EDM está associado a:',options:['Avaliar, direcionar e monitorar a governança','Escrever, depurar e manter programas','Criptografar, descriptografar e migrar dados','Excluir, duplicar e mover arquivos'],answer:0,explanation:'EDM significa Evaluate, Direct and Monitor: avaliar, direcionar e monitorar. É o domínio de objetivos de governança, distinto dos domínios de gestão.'},
{id:'g08',category:'Governança e Gestão de TI',topic:'p6-1',prompt:'Qual situação melhor representa alinhamento estratégico de TI?',options:['Escolher ferramentas exclusivamente pela popularidade','Priorizar iniciativas tecnológicas conforme objetivos e necessidades da organização','Comprar infraestrutura antes de conhecer a demanda','Avaliar projetos apenas pelo número de linhas de código'],answer:1,explanation:'Alinhamento estratégico conecta decisões e investimentos de TI aos objetivos institucionais. Popularidade e volume de código, isoladamente, não demonstram esse alinhamento.'},
{id:'g09',category:'Governança e Gestão de TI',topic:'p6-12',prompt:'Qual combinação é central para avaliar um risco?',options:['Cor da interface e resolução do monitor','Quantidade de usuários e nome do fornecedor, sempre','Probabilidade de ocorrência e consequências ou impacto','Apenas a idade do equipamento'],answer:2,explanation:'Risco envolve incerteza e consequências. Probabilidade e impacto são dimensões comuns de sua avaliação; um único atributo, como idade do equipamento, não basta.'},
{id:'g10',category:'Governança e Gestão de TI',topic:'p6-11',prompt:'No modelo clássico de níveis de maturidade do CMMI, o nível 3 é denominado:',options:['Inicial','Gerenciado','Definido','Em otimização'],answer:2,explanation:'Na escala clássica: 1 Inicial, 2 Gerenciado, 3 Definido, 4 Gerenciado Quantitativamente e 5 Em Otimização. O enunciado delimita essa escala, pois modelos e versões devem ser identificados.'},
{id:'g11',category:'Governança e Gestão de TI',topic:'p6-2',prompt:'Qual é a função mais característica de um Planejamento Estratégico de TI (PETI)?',options:['Definir exclusivamente a senha dos servidores','Orientar a TI de acordo com a estratégia da organização','Substituir todos os procedimentos operacionais','Registrar somente incidentes resolvidos'],answer:1,explanation:'O PETI orienta a atuação de TI em relação à estratégia organizacional. Registro de incidentes e procedimentos operacionais têm outros objetivos.'},
{id:'g12',category:'Governança e Gestão de TI',topic:'p6-13',prompt:'Um indicador de disponibilidade deve permitir avaliar principalmente:',options:['O tempo em que um serviço esteve disponível conforme os critérios de medição acordados','A quantidade de cores da interface','O número de linhas no contrato','A quantidade de senhas cadastradas'],answer:0,explanation:'Disponibilidade relaciona a capacidade do serviço de desempenhar sua função quando necessário. A medição precisa explicitar período, critérios e exclusões acordadas.'},
{id:'pt01',category:'Língua Portuguesa',topic:'p1-1',prompt:'Em “Embora o sistema fosse novo, apresentou falhas”, a oração iniciada por “embora” expressa:',options:['Causa','Concessão','Finalidade','Condição'],answer:1,explanation:'“Embora” introduz concessão: a informação sobre o sistema novo contraria uma expectativa, sem impedir a ocorrência de falhas.'},
{id:'pt02',category:'Língua Portuguesa',topic:'p1-12',prompt:'Em “O servidor estava indisponível; por isso, o atendimento foi adiado”, a expressão “por isso” estabelece:',options:['Conclusão ou consequência do fato anterior','Comparação entre servidores','Alternância entre hipóteses','Uma explicação de sentido oposto ao texto'],answer:0,explanation:'“Por isso” retoma a indisponibilidade como fundamento da consequência: o adiamento do atendimento.'},
{id:'pt03',category:'Língua Portuguesa',topic:'p1-9',prompt:'Assinale a frase em que o uso da crase está correto.',options:['O técnico começou à revisar o relatório.','O relatório foi enviado à todos.','A servidora foi à escola.','A equipe trabalha de segunda à sexta.'],answer:2,explanation:'“Ir a” exige preposição, e “a escola” admite artigo: a + a = à. Não há crase antes de verbo ou de “todos”; em “de segunda a sexta”, não se emprega crase nessa construção.'},
{id:'pt04',category:'Língua Portuguesa',topic:'p1-7',prompt:'Qual frase está de acordo com a norma-padrão?',options:['Fazem dois anos que o sistema foi instalado.','Faz dois anos que o sistema foi instalado.','Fazem dois ano que o sistema foi instalado.','Faz dois anos que os sistemas foi instalado.'],answer:1,explanation:'O verbo “fazer”, quando indica tempo decorrido, é impessoal e permanece no singular: “Faz dois anos”.'},
{id:'pt05',category:'Língua Portuguesa',topic:'p1-7',prompt:'Considerando “haver” no sentido de existir, qual construção está correta?',options:['Houveram incidentes na rede.','Houve incidentes na rede.','Haviam vários incidentes, no sentido de existir.','Houveram vários problemas ontem.'],answer:1,explanation:'“Haver” no sentido de existir é impessoal e fica no singular. Por isso, diz-se “Houve incidentes”.'},
{id:'pt06',category:'Língua Portuguesa',topic:'p1-10',prompt:'Qual frase evita a separação indevida entre sujeito e verbo por vírgula?',options:['Os técnicos do setor, concluíram a manutenção.','Os técnicos do setor concluíram a manutenção.','Os técnicos, do setor concluíram a manutenção.','Os técnicos do setor concluíram, a manutenção.'],answer:1,explanation:'Não se separa sujeito de verbo nem verbo de seu complemento direto por vírgula nessa construção. A segunda alternativa mantém a estrutura sintática adequada.'},
{id:'pt07',category:'Língua Portuguesa',topic:'p1-15',prompt:'A forma passiva analítica correspondente a “A analista revisou o relatório” é:',options:['O relatório revisou a analista.','Revisava-se a analista pelo relatório.','O relatório foi revisado pela analista.','A analista tinha revisado o relatório.'],answer:2,explanation:'Na passiva analítica, o objeto da ativa torna-se sujeito paciente: “O relatório foi revisado pela analista”. O tempo verbal é preservado.'},
{id:'pt08',category:'Língua Portuguesa',topic:'p1-1',prompt:'O texto afirma: “Alguns usuários tiveram dificuldade para acessar o portal”. Qual conclusão é necessariamente sustentada?',options:['Todos os usuários tiveram dificuldade.','Nenhum usuário conseguiu acessar o portal.','Ao menos uma parte dos usuários teve dificuldade.','A dificuldade foi causada obrigatoriamente por malware.'],answer:2,explanation:'“Alguns” sustenta a existência de usuários com dificuldade, mas não permite afirmar que todos tiveram o problema, que ninguém acessou ou qual foi a causa.'},
{id:'es01',category:'Engenharia de Software',topic:'p7-5',prompt:'“O sistema deve permitir cadastrar um chamado” é, principalmente, um requisito:',options:['Funcional','De disponibilidade exclusivamente','De portabilidade exclusivamente','Físico de cabeamento'],answer:0,explanation:'O enunciado descreve uma função que o sistema deve oferecer. Requisitos não funcionais tratam, por exemplo, de desempenho, segurança ou disponibilidade.'},
{id:'es02',category:'Engenharia de Software',topic:'p7-3',prompt:'No Scrum, quem é responsável pela gestão eficaz do Product Backlog?',options:['O Product Owner','Qualquer fornecedor, exclusivamente','O gerente de infraestrutura, obrigatoriamente','Somente o Scrum Master, com exclusão do Product Owner'],answer:0,explanation:'O Product Owner é responsável pela gestão eficaz do Product Backlog, podendo delegar trabalho, mas mantendo a responsabilidade.'},
{id:'es03',category:'Engenharia de Software',topic:'p7-3',prompt:'Em um fluxo Kanban, limitar o trabalho em progresso (WIP) ajuda a:',options:['Iniciar o máximo de tarefas simultâneas sem restrições','Controlar o fluxo e evidenciar gargalos','Eliminar a necessidade de concluir atividades','Garantir que nunca existam filas'],answer:1,explanation:'Limites de WIP ajudam a controlar o trabalho em andamento, reduzir excesso de tarefas simultâneas e revelar gargalos. Eles não garantem a inexistência de filas.'},
{id:'es04',category:'Engenharia de Software',topic:'p7-7',prompt:'Qual diagrama UML é especialmente apropriado para mostrar mensagens trocadas entre participantes ao longo do tempo?',options:['Diagrama de sequência','Diagrama de implantação apenas','Diagrama de pacotes apenas','Diagrama entidade-relacionamento'],answer:0,explanation:'O diagrama de sequência representa interações e a ordem temporal das mensagens entre participantes.'},
{id:'es05',category:'Engenharia de Software',topic:'p7-10',prompt:'Um teste que verifica uma função de cálculo isolada, usando dependências controladas, é tipicamente:',options:['Teste de aceitação do sistema completo','Teste unitário','Teste de recuperação de desastre','Teste físico de rede'],answer:1,explanation:'Testes unitários verificam unidades pequenas e isoladas de comportamento. Integração e aceitação possuem outros escopos.'},
{id:'es06',category:'Engenharia de Software',topic:'p7-13',prompt:'Refatoração consiste em:',options:['Modificar a estrutura interna do código preservando seu comportamento observável','Adicionar sempre uma nova funcionalidade','Excluir testes antes de alterar o código','Trocar necessariamente a linguagem de programação'],answer:0,explanation:'Refatorar melhora a estrutura interna sem mudar o comportamento observável. Testes ajudam a conferir essa preservação.'},
{id:'es07',category:'Engenharia de Software',topic:'p7-14',prompt:'Ao mesclar branches, o Git informa um conflito de conteúdo. O procedimento adequado é:',options:['Presumir que todo conflito é um ataque','Resolver o conteúdo conflitante, revisar e registrar a resolução','Apagar obrigatoriamente todo o repositório','Executar push com força sem inspecionar o código'],answer:1,explanation:'Conflitos exigem análise do conteúdo, escolha ou combinação correta das alterações e registro da resolução. O aviso não significa perda irrecuperável do repositório.'},
{id:'pr01',category:'Programação',topic:'p9-8',prompt:'Em Python: a = [1, 2]; b = a; b.append(3). Qual é o valor de a ao final?',options:['[1, 2]','[3]','[1, 2, 3]','Ocorre erro obrigatoriamente'],answer:2,explanation:'As variáveis a e b referenciam a mesma lista mutável. A chamada append modifica essa lista, observada por ambas.'},
{id:'pr02',category:'Programação',topic:'p9-4',prompt:'Em orientação a objetos, encapsulamento está mais relacionado a:',options:['Expor toda a representação interna sem controle','Agrupar dados e comportamento, controlando acesso aos detalhes internos','Impedir qualquer método público','Usar apenas funções globais'],answer:1,explanation:'Encapsulamento reúne estado e comportamento e controla o acesso à representação interna. Não implica proibir toda interação pública.'},
{id:'pr03',category:'Programação',topic:'p9-11',prompt:'Segundo a semântica HTTP, o método GET deve ser usado principalmente para:',options:['Solicitar uma representação de um recurso','Excluir recursos como efeito pretendido','Substituir integralmente um recurso como efeito pretendido','Alterar senhas como operação principal'],answer:0,explanation:'GET solicita uma representação e tem semântica segura. Alterações de estado não devem ser o efeito pretendido de uma requisição GET.'},
{id:'pr04',category:'Programação',topic:'p9-9',prompt:'Em JavaScript, qual é o resultado de 5 === "5"?',options:['true, porque os caracteres são iguais','false, porque a igualdade estrita não converte os tipos','Uma exceção de sintaxe','A string "true"'],answer:1,explanation:'=== compara sem conversão implícita de tipo. Um número e uma string são diferentes na igualdade estrita.'},
{id:'pr05',category:'Programação',topic:'p9-5',prompt:'Uma classe abstrata, em linguagens como Java, caracteriza-se por:',options:['Poder ser instanciada diretamente em qualquer caso','Não poder possuir métodos implementados','Não poder ser instanciada diretamente, podendo servir de base a subclasses','Ser obrigatoriamente uma interface de rede'],answer:2,explanation:'Classes abstratas não são instanciadas diretamente e podem possuir métodos abstratos e métodos concretos.'},
{id:'rl01',category:'Raciocínio Lógico e Matemático',topic:'p2-4',prompt:'A negação de “p e q” é logicamente equivalente a:',options:['não p e não q','não p ou não q','p ou q','p se, e somente se, q'],answer:1,explanation:'Pela lei de De Morgan, ¬(p ∧ q) equivale a ¬p ∨ ¬q. Basta que pelo menos uma das proposições seja falsa.'},
{id:'rl02',category:'Raciocínio Lógico e Matemático',topic:'p2-3',prompt:'A condicional “se p, então q” é falsa somente quando:',options:['p é verdadeira e q é falsa','p é falsa e q é verdadeira','p e q são falsas','p e q são verdadeiras'],answer:0,explanation:'A condicional p → q só é falsa no caso V → F. Nas demais combinações, é verdadeira.'},
{id:'rl03',category:'Raciocínio Lógico e Matemático',topic:'p2-4',prompt:'A proposição “p implica q” é equivalente a:',options:['p e q','não p ou q','p ou não q','não p e não q'],answer:1,explanation:'A equivalência fundamental da condicional é p → q ≡ ¬p ∨ q.'},
{id:'rl04',category:'Raciocínio Lógico e Matemático',topic:'p2-8',prompt:'Um valor de R$ 100 sofre aumento de 10% e depois redução de 10% sobre o novo valor. Qual é o resultado?',options:['R$ 100','R$ 99','R$ 101','R$ 90'],answer:1,explanation:'Após o aumento, o valor é R$ 110. A redução de 10% é de R$ 11, resultando em R$ 99. Percentuais sucessivos incidem sobre bases diferentes.'},
{id:'rl05',category:'Raciocínio Lógico e Matemático',topic:'p2-12',prompt:'Ao lançar um dado comum e equilibrado de seis faces, qual é a probabilidade de sair um número par?',options:['1/6','1/3','1/2','2/3'],answer:2,explanation:'Os resultados pares são 2, 4 e 6: três entre seis resultados equiprováveis. Portanto, 3/6 = 1/2.'},
{id:'mp01',category:'Legislação do Ministério Público',topic:'p5-1',prompt:'Segundo o art. 127, § 1º, da Constituição, são princípios institucionais do Ministério Público:',options:['Hierarquia militar, disciplina e subordinação política','Unidade, indivisibilidade e independência funcional','Publicidade, concorrência e economicidade exclusivamente','Vitaliciamento automático e eleição direta de todos os membros'],answer:1,explanation:'A Constituição enumera unidade, indivisibilidade e independência funcional como princípios institucionais do MP.',source:'https://www2.camara.leg.br/atividade-legislativa/legislacao/constituicao1988'},
{id:'mp02',category:'Legislação do Ministério Público',topic:'p5-1',prompt:'De acordo com o art. 128 da Constituição, o Ministério Público abrange:',options:['Somente o Ministério Público Federal','O Ministério Público da União e os Ministérios Públicos dos Estados','Somente o Ministério Público do Trabalho','Exclusivamente órgãos subordinados ao Judiciário'],answer:1,explanation:'A Constituição distingue o Ministério Público da União e os Ministérios Públicos dos Estados. O MP não é órgão subordinado ao Poder Judiciário.',source:'https://www2.camara.leg.br/atividade-legislativa/legislacao/constituicao1988'},
{id:'mp03',category:'Legislação do Ministério Público',topic:'p5-5',prompt:'Pela regra geral do art. 9º da Lei 8.625/1993, o Procurador-Geral de Justiça de um Ministério Público estadual é nomeado pelo:',options:['Chefe do Poder Executivo, a partir de lista tríplice formada na forma da lei','Presidente do Tribunal de Justiça, sem lista','Presidente da República em todos os estados','Conselho Federal da OAB, para mandato vitalício'],answer:0,explanation:'O art. 9º prevê lista tríplice dentre integrantes da carreira e nomeação pelo Chefe do Poder Executivo, com mandato de dois anos e possibilidade de uma recondução.',source:'https://www2.camara.leg.br/legin/fed/lei/1993/lei-8625-12-fevereiro-1993-363257-normaatualizada-pl.html'},
{id:'mp04',category:'Legislação do Ministério Público',topic:'p5-7',prompt:'Qual destes é órgão da Administração Superior do MP, conforme o art. 5º da Lei 8.625/1993?',options:['Conselho Superior do Ministério Público','Delegacia de Polícia Civil','Tribunal de Contas da União','Secretaria Municipal de Educação'],answer:0,explanation:'O art. 5º inclui a Procuradoria-Geral de Justiça, o Colégio de Procuradores, o Conselho Superior e a Corregedoria-Geral entre os órgãos da Administração Superior.',source:'https://www2.camara.leg.br/legin/fed/lei/1993/lei-8625-12-fevereiro-1993-363257-normaatualizada-pl.html'},
{id:'al01',category:'Algoritmos e Estruturas de Dados',topic:'p8-10',prompt:'Para usar corretamente a busca binária clássica em um vetor, é necessário que os elementos estejam:',options:['Ordenados segundo o critério de comparação usado','Todos duplicados','Em ordem aleatória obrigatoriamente','Armazenados apenas em uma pilha'],answer:0,explanation:'A busca binária divide o espaço de busca aproveitando a ordenação. Sem essa condição, descartar metade do vetor pode eliminar o elemento procurado.'},
{id:'al02',category:'Algoritmos e Estruturas de Dados',topic:'p8-9',prompt:'Uma pilha segue a política:',options:['FIFO: primeiro a entrar, primeiro a sair','LIFO: último a entrar, primeiro a sair','Saída aleatória obrigatória','Ordenação crescente automática'],answer:1,explanation:'Em uma pilha, o último item inserido é o primeiro removido: LIFO. Filas comuns usam FIFO.'},
{id:'al03',category:'Algoritmos e Estruturas de Dados',topic:'p8-8',prompt:'Em uma função recursiva que calcula o fatorial de um inteiro não negativo, qual é o papel do caso-base?',options:['Garantir a chamada recursiva infinita','Definir uma situação que retorna sem nova chamada recursiva','Ordenar automaticamente os parâmetros','Transformar a recursão em uma consulta SQL'],answer:1,explanation:'O caso-base fornece uma condição de parada. Por exemplo, 0! = 1, e a chamada para n = 0 retorna diretamente.'},
{id:'bd01',category:'Banco de Dados',topic:'p13-6',prompt:'Em uma tabela relacional, uma chave primária deve:',options:['Permitir valores nulos e duplicados livremente','Identificar unicamente cada linha e não admitir nulos','Ser sempre uma coluna de texto','Ser obrigatoriamente igual a todas as chaves estrangeiras'],answer:1,explanation:'A chave primária identifica cada linha de forma única e seus componentes não admitem valores nulos.'},
{id:'bd02',category:'Banco de Dados',topic:'p13-11',prompt:'Em uma consulta SQL com agregação, a cláusula HAVING é usada para:',options:['Filtrar grupos, inclusive por resultados de agregação','Substituir obrigatoriamente todos os JOINs','Criar índices físicos','Excluir uma tabela'],answer:0,explanation:'WHERE filtra linhas antes do agrupamento; HAVING permite filtrar os grupos resultantes, por exemplo com COUNT(*) > 5.'},
{id:'bd03',category:'Banco de Dados',topic:'p13-15',prompt:'Nas propriedades ACID, atomicidade significa que uma transação:',options:['Executa todas as suas operações ou não efetiva nenhuma delas','Nunca precisa de controle de concorrência','Sempre executa em menos de um segundo','Dispensa armazenamento persistente'],answer:0,explanation:'Atomicidade expressa o princípio de tudo ou nada. Não deve ser confundida com isolamento, consistência ou durabilidade.'},
{id:'rd01',category:'Redes de Computadores',topic:'p10-8',prompt:'Qual serviço é usado principalmente para resolver nomes de domínio em registros, como endereços IP?',options:['DNS','DHCP','NTP','FTP'],answer:0,explanation:'DNS resolve nomes de domínio e outros registros. DHCP distribui parâmetros de rede; NTP sincroniza relógios; FTP transfere arquivos.'},
{id:'rd02',category:'Redes de Computadores',topic:'p10-7',prompt:'Qual característica é própria do TCP, em comparação ao UDP?',options:['Não possui nenhum controle de entrega','Oferece um fluxo de bytes confiável e ordenado entre os extremos','É obrigatoriamente mais rápido em qualquer aplicação','Não utiliza portas'],answer:1,explanation:'O TCP oferece mecanismos de confiabilidade, controle e ordenação. O UDP transmite datagramas sem essas garantias próprias do TCP.'},
{id:'rd03',category:'Redes de Computadores',topic:'p10-6',prompt:'Uma sub-rede IPv4 /26 possui quantos endereços totais?',options:['26','32','64','128'],answer:2,explanation:'Restam 32 − 26 = 6 bits para endereços no bloco: 2⁶ = 64. A questão pede endereços totais, não a quantidade convencional de hosts utilizáveis.'},
{id:'sg01',category:'Segurança da Informação',topic:'p12-1',prompt:'Evitar alterações não autorizadas de dados relaciona-se principalmente à:',options:['Integridade','Disponibilidade apenas','Compressão','Elasticidade'],answer:0,explanation:'Integridade está relacionada à precisão e completude, protegendo contra alterações indevidas. Confidencialidade trata do acesso e divulgação; disponibilidade, do acesso quando requerido.'},
{id:'sg02',category:'Segurança da Informação',topic:'p12-10',prompt:'Qual combinação é um exemplo de autenticação com fatores de categorias diferentes?',options:['Senha e PIN, ambos memorizados','Duas senhas iguais','Senha e um token físico de posse do usuário','Duas perguntas de conhecimento pessoal'],answer:2,explanation:'Senha é algo que o usuário sabe; token físico é algo que ele possui. Duas credenciais da mesma categoria não formam, por si, fatores de categorias diferentes.'},
{id:'sg03',category:'Segurança da Informação',topic:'p12-7',prompt:'Na criptografia assimétrica, usa-se tipicamente:',options:['Um par de chaves relacionadas: pública e privada','Uma única senha pública para todos os usuários','Somente algoritmos de compressão','A mesma chave secreta compartilhada por todos como característica definidora'],answer:0,explanation:'Sistemas assimétricos utilizam um par de chaves relacionadas, uma pública e outra privada. O uso depende da operação, como cifrar ou assinar.'},
{id:'so01',category:'Sistemas Operacionais',topic:'p11-9',prompt:'Em permissões tradicionais de arquivos Linux, chmod 640 corresponde a:',options:['Dono: leitura e escrita; grupo: leitura; outros: nenhuma permissão','Dono: execução; grupo: escrita; outros: leitura','Leitura e escrita para todos','Execução para todos, sem leitura'],answer:0,explanation:'Na notação octal, leitura = 4, escrita = 2 e execução = 1. Assim, 6 = leitura + escrita; 4 = leitura; 0 = nenhuma permissão.'},
{id:'so02',category:'Sistemas Operacionais',topic:'p11-11',prompt:'O Active Directory Domain Services é usado principalmente para:',options:['Centralizar objetos de diretório, autenticação e administração em um domínio','Substituir a função física de um switch','Compactar exclusivamente arquivos de áudio','Eliminar a necessidade de qualquer política de acesso'],answer:0,explanation:'O AD DS oferece serviços de diretório e recursos de autenticação e administração centralizada de objetos do domínio.'},
{id:'nu01',category:'Computação em Nuvem e Infraestrutura',topic:'p15-2',prompt:'Em qual modelo o consumidor normalmente recebe máquinas virtuais e gerencia o sistema operacional e suas aplicações?',options:['IaaS','SaaS','Somente armazenamento de senhas','Correio tradicional'],answer:0,explanation:'IaaS fornece recursos de infraestrutura. O consumidor costuma gerenciar sistema operacional e aplicações; em SaaS, consome uma aplicação pronta.'},
{id:'hw01',category:'Hardware, Manutenção e Suporte Técnico',topic:'p14-2',prompt:'Qual característica descreve a memória RAM usual de um computador?',options:['É normalmente volátil e usada no trabalho com dados e programas em execução','Mantém necessariamente os dados sem energia, como um SSD','Substitui obrigatoriamente o processador','Serve apenas para armazenar o firmware da placa-mãe'],answer:0,explanation:'A RAM principal usual é volátil: perde os dados sem alimentação. SSD e HDD são exemplos de armazenamento não volátil.'},
{id:'dc01',category:'Direito Constitucional',topic:'p3-2',prompt:'Qual alternativa apresenta um fundamento da República Federativa do Brasil previsto no art. 1º da Constituição?',options:['Dignidade da pessoa humana','Subordinação dos estados a empresas privadas','Vitaliciedade de todos os servidores','Eliminação do pluralismo político'],answer:0,explanation:'A dignidade da pessoa humana está entre os fundamentos previstos no art. 1º, ao lado de soberania, cidadania, valores sociais do trabalho e da livre iniciativa e pluralismo político.',source:'https://www2.camara.leg.br/atividade-legislativa/legislacao/constituicao1988'},
{id:'dc02',category:'Direito Constitucional',topic:'p3-7',prompt:'O art. 37, caput, da Constituição estabelece expressamente os princípios de:',options:['Legalidade, impessoalidade, moralidade, publicidade e eficiência','Sigilo absoluto, pessoalidade e arbitrariedade','Exclusividade, informalidade e hierarquia militar','Competitividade e lucro, apenas'],answer:0,explanation:'Legalidade, impessoalidade, moralidade, publicidade e eficiência são os princípios expressos no caput do art. 37, frequentemente lembrados pela sigla LIMPE.',source:'https://www2.camara.leg.br/atividade-legislativa/legislacao/constituicao1988'},
{id:'da01',category:'Direito Administrativo',topic:'p4-8',prompt:'Qual alternativa contém uma modalidade de licitação prevista no art. 28 da Lei 14.133/2021?',options:['Diálogo competitivo','Convite','Tomada de preços','Consulta de preços como modalidade autônoma'],answer:0,explanation:'A Lei 14.133/2021 prevê pregão, concorrência, concurso, leilão e diálogo competitivo. Convite e tomada de preços não compõem a lista do art. 28 dessa lei.',source:'https://www2.camara.leg.br/legin/fed/lei/2021/lei-14133-1-abril-2021-791222-normaatualizada-pl.pdf'}
];
